package main

import (
	"fmt"
	"net/http"
	"os/exec"
	"strings"
)

// 上传文件管理器：接收归档上传并调用系统 tar 解压
func uploadHandler(w http.ResponseWriter, r *http.Request) {
	// 入口：multipart 表单字段 archive，文件名完全由客户端控制
	file, header, err := r.FormFile("archive")
	if err != nil {
		http.Error(w, "upload failed", 400)
		return
	}
	defer file.Close()

	// 弱防御：仅黑名单过滤分号、管道、连接符等关键字
	name := header.Filename
	for _, bad := range []string{";", "|", "&", "rm", "del"} {
		if strings.Contains(name, bad) {
			http.Error(w, "illegal name", 400)
			return
		}
	}

	dst := "/var/uploads/" + name
	// sink：文件名未转义直接拼入 sh -c 执行的命令串
	cmd := exec.Command("sh", "-c", "tar -xzf "+dst+" -C /var/extract/")
	out, err := cmd.CombinedOutput()
	if err != nil {
		fmt.Fprintf(w, "extract error: %v: %s", err, out)
		return
	}
	fmt.Fprintln(w, "extracted ok")
}

func main() {
	http.HandleFunc("/upload", uploadHandler)
	http.ListenAndServe(":8080", nil)
}
