import java.io.InputStream;
import java.net.URLDecoder;

/** 邮件模板服务：按模板名调用外部渲染工具生成 HTML 并投递 */
public class MailTemplateService {

    // 弱防御：仅删除明文分号，未覆盖其他 shell 元字符
    static String sanitize(String raw) {
        return raw.replace(";", "");
    }

    // 入口：GET /mail/render?template=... 的原始请求参数
    public String renderTemplate(String rawTemplate) throws Exception {
        String filtered = sanitize(rawTemplate);
        // 缺陷：过滤之后才做 URL 解码，%3B 在此处还原成分号
        String template = URLDecoder.decode(filtered, "UTF-8");

        // 拼接 shell 命令：渲染模板后交给 sendmail 投递
        String cmd = "pandoc templates/" + template + ".md -t html | sendmail -t";
        Process proc = Runtime.getRuntime().exec(new String[]{"/bin/sh", "-c", cmd});

        InputStream in = proc.getInputStream();
        StringBuilder out = new StringBuilder();
        int b;
        while ((b = in.read()) != -1) {
            out.append((char) b);
        }
        return out.toString();
    }
}
