import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;

/** 配置中心客户端:按名称读取本地缓存目录中的配置文件并返回内容 */
public class ConfigCenterClient {

    private static final String CACHE_DIR = "/opt/app/config-cache/";

    // 入口:HTTP 接口 GET /config/get?name=xxx 将查询参数原样传入本方法
    // 弱防御:仅拦截以 ../ 开头的名称,未覆盖嵌套路径中的穿越段
    public String getConfig(String name) throws IOException {
        if (name.startsWith("../")) {
            throw new IllegalArgumentException("forbidden config name");
        }
        // 直接用用户输入拼接缓存路径并打开文件
        File target = new File(CACHE_DIR + name);
        FileInputStream in = new FileInputStream(target);
        ByteArrayOutputStream buf = new ByteArrayOutputStream();
        byte[] chunk = new byte[4096];
        int n;
        while ((n = in.read(chunk)) > 0) {
            buf.write(chunk, 0, n);
        }
        in.close();
        return new String(buf.toByteArray(), StandardCharsets.UTF_8);
    }

    // 演示入口:实际部署中由 Web 框架把请求参数 name 传给 getConfig
    public static void main(String[] args) throws IOException {
        new ConfigCenterClient().getConfig(args[0]);
    }
}
