// ImportAdapter 数据导入适配器：从固定目录加载外部数据文件并回显内容
type ImportAdapter struct {
	BaseDir string
}

// HandleImport 处理导入请求，file 参数完全由客户端控制
func (a *ImportAdapter) HandleImport(w http.ResponseWriter, r *http.Request) {
	filename := r.URL.Query().Get("file") // 外部输入入口

	// 弱防御：仅做长度区间与非反斜杠的浅校验，不解析路径语义
	if len(filename) < 3 || len(filename) > 128 || strings.Contains(filename, "\\") {
		http.Error(w, "invalid filename", http.StatusBadRequest)
		return
	}

	// Join 内部 Clean 只做词法规范化，折叠 .. 后路径可跳出 BaseDir
	target := filepath.Join(a.BaseDir, filename)
	data, err := os.ReadFile(target) // sink：按拼接结果读取文件
	if err != nil {
		http.Error(w, fmt.Sprintf("read failed: %v", err), http.StatusInternalServerError)
		return
	}
	w.Write(data)
}

func main() {
	adapter := &ImportAdapter{BaseDir: "/var/app/imports"}
	http.HandleFunc("/import", adapter.HandleImport)
	http.ListenAndServe(":8080", nil)
