package com.corp.auth.middleware;

import org.w3c.dom.Document;
import org.w3c.dom.NodeList;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;

/** 权限校验中间件：解析请求携带的 XML 授权策略，判定是否放行 */
public class PolicyAuthFilter {

    public boolean doFilter(HttpServletRequest request, HttpServletResponse response) throws Exception {
        // 入口：客户端通过自定义请求头提交 XML 权限策略
        String policyXml = request.getHeader("X-Auth-Policy");
        if (policyXml == null || policyXml.isEmpty()) {
            response.sendError(401, "policy required");
            return false;
        }
        // 弱防御：仅删除 SYSTEM 关键字，试图阻止外部实体声明
        String cleaned = policyXml.replace("SYSTEM", "");
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
        // 未调用 setFeature 关闭 DTD 与外部实体，解析器保持默认允许
        DocumentBuilder builder = dbf.newDocumentBuilder();
        Document doc = builder.parse(new ByteArrayInputStream(cleaned.getBytes(StandardCharsets.UTF_8)));
        NodeList roles = doc.getElementsByTagName("role");
        return roles.getLength() > 0 && "admin".equals(roles.item(0).getTextContent());
    }
}
