import java.util.Base64;

/** 订单处理后台任务：从消息中间件拉取待处理订单并反序列化 */
public class OrderProcessTask {

    // 黑名单：仅拦截已知危险类关键字（弱防御）
    private static final String[] BLACKLIST = {"runtime", "processbuilder", "invokertransformer"};

    // 后台任务入口：MQ 消费者回调，payload 为 Base64 编码的序列化订单报文
    public void onMessage(String payload) throws Exception {
        byte[] raw = Base64.getDecoder().decode(payload);
        String preview = new String(raw, "UTF-8").toLowerCase();
        for (String kw : BLACKLIST) {
            if (preview.contains(kw)) {
                return; // 命中黑名单则丢弃该消息
            }
        }
        ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(raw));
        Object order = ois.readObject(); // sink：反序列化不可信数据
        ois.close();
        handleOrder(order);
    }

    private void handleOrder(Object order) {
        System.out.println("处理订单: " + order.getClass().getName());
    }
}
