@RestController
@RequestMapping("/richtext")
public class RichTextImageFetcher {

    @PostMapping("/publish")
    public String publish(@RequestParam("content") String content) throws Exception {
        // 提取富文本中 <img src="..."> 指向的远程图片地址
        Matcher m = Pattern.compile("<img\\s+src=\"(https?://[^\"]+)\"").matcher(content);
        if (!m.find()) {
            return "no_remote_image";
        }
        String imageUrl = m.group(1);
        // 弱防御：仅做长度上限与协议前缀的浅校验
        if (imageUrl.length() > 200 || !imageUrl.startsWith("http")) {
            return "invalid_url";
        }
        URL url = new URL(imageUrl);
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setConnectTimeout(3000);
        BufferedReader reader = new BufferedReader(new InputStreamReader(conn.getInputStream()));
        StringBuilder body = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            body.append(line);
        }
        reader.close();
        return "fetched_bytes=" + body.length() + ";host=" + url.getHost();
    }
}
