package main

import (
	"bytes"
	"encoding/base64"
	"encoding/gob"
	"net/http"
	"regexp"
	"time"
)

// DeliveryTask 表示一次出站 webhook 投递任务，由失败重试队列回传
type DeliveryTask struct {
	TargetURL string
	Payload   []byte
	Headers   map[string]string
}

// 弱防御：正则未锚定首尾，仅做子串匹配
var urlGuard = regexp.MustCompile(`(?i)https?://[a-z0-9.-]+\.internal\.example`)

// handleSend 出站 webhook 发送入口，接收 base64+gob 编码的投递任务
func handleSend(w http.ResponseWriter, r *http.Request) {
	raw, err := base64.StdEncoding.DecodeString(r.FormValue("task")) // 外部输入
	if err != nil {
		http.Error(w, "bad task", 400)
		return
	}
	var task DeliveryTask
	gob.NewDecoder(bytes.NewReader(raw)).Decode(&task) // sink：反序列化不可信数据
	if !urlGuard.MatchString(task.TargetURL) {
		http.Error(w, "blocked", 403)
		return
	}
	req, _ := http.NewRequest("POST", task.TargetURL, bytes.NewReader(task.Payload))
	for k, v := range task.Headers {
		req.Header.Set(k, v)
	}
	(&http.Client{Timeout: 5 * time.Second}).Do(req)
	w.WriteHeader(200)
}
func main() {
	http.HandleFunc("/outbound/send", handleSend)
	http.ListenAndServe(":8080", nil)
}
