  const { sourceUrl, connector } = req.body; // 外部输入入口
  let body = '';
  if (connector === 'legacy') {
    // legacy 连接器直接使用原生 http/https，不经过 guardForFetch
    const client = sourceUrl.startsWith('https') ? https : http;
    await new Promise((resolve, reject) => {
      const rq = client.request(sourceUrl, (resp) => { // 未校验的 SSRF sink
        resp.on('data', (c) => { body += c; });
        resp.on('end', resolve);
      });
      rq.on('error', reject);
      rq.end();
    });
  } else {
    const resp = await fetch(guardForFetch(sourceUrl)); // 仅此分支有弱校验
    body = await resp.text();
  }
  const report = `<report name="export">${body}</report>`;
