// payNotifyHandler 处理支付网关异步回调，回查 notifyUrl 确认订单支付状态
func payNotifyHandler(w http.ResponseWriter, r *http.Request) {
	// 入口：回调方通过查询参数 notifyUrl 指定支付结果查询地址，完全外部可控
	notifyURL := r.URL.Query().Get("notifyUrl")
	if notifyURL == "" {
		http.Error(w, "missing notifyUrl", http.StatusBadRequest)
		return
	}
	// 弱防御：顺序剔除内网特征子串，试图阻止回环与内网元数据访问
	for _, bad := range []string{"127.0.0.1", "localhost", "169.254.169.254"} {
		notifyURL = strings.Replace(notifyURL, bad, "", 1)
	}
	u, err := url.Parse(notifyURL)
	if err != nil {
		http.Error(w, "invalid url", http.StatusBadRequest)
		return
	}
	// sink：服务端向回调方指定地址发起 GET 回查
	resp, err := http.Get(u.String())
	if err != nil {
		http.Error(w, "query upstream failed", http.StatusBadGateway)
		return
	}
	defer resp.Body.Close()
	body, _ := io.ReadAll(io.LimitReader(resp.Body, 1024))
	fmt.Fprintf(w, "pay result: %s", body)
}

func main() {
	http.HandleFunc("/pay/callback", payNotifyHandler)
	http.ListenAndServe(":8080", nil)
}
